<?php
declare(strict_types=1);
function learning_paths():array{return [
 'first-contact'=>['id'=>'first-contact','title'=>'First contact with Beyond Spacetime','level'=>'Beginner','description'=>'Understand the difference between an observation, a mathematical model and the physical explanation proposed for it.','steps'=>[['physical-first','Start with measured quantities and the distinction between geometry and mechanism.'],['foundations','Learn the twelve research commitments and their status.'],['photon-mass','Distinguish rest mass from energy and momentum.'],['cosmic-evolution','Keep the hot Big Bang reference alongside proposed physical expansion.'],['evidence','Decide what would actually count as a test.']],'quiz'=>[['Can a simulation alone establish that photons have mass?','No. A conditional calculation must be distinguished from independent empirical evidence.'],['Does rejecting a literal fabric metaphor require denying expansion?','No. Increasing physical separations and a hot early phase remain possible.']]],
 'light-and-measurement'=>['id'=>'light-and-measurement','title'=>'Follow a photon to the telescope','level'=>'Intermediate','description'=>'Connect emission, propagation, timekeeping and calibrated astronomical inference.','steps'=>[['photon-mass','Start with the positive-gap and zero-gap controls.'],['light-history','Compare energy change, group speed and arrival stretching.'],['clocks','Keep physical clock counts separate from model progression.'],['distances','Explore parallax, extinction and travel-time inference.'],['evidence','Compare observables rather than fitting a desired conclusion.']],'quiz'=>[['Does losing half a photon packet’s energy necessarily halve its speed?','No. In the massless control the speed remains C, and for a very small gap the speed deficit can remain tiny.'],['Does dimming always mean an object is farther away?','No. Extinction, intrinsic luminosity and calibration can affect flux. Independent geometric anchors matter.']]],
 'greater-cosmos'=>['id'=>'greater-cosmos','title'=>'From cosmic expansion to greater domains','level'=>'Advanced','description'=>'Investigate boundary growth, tidal interactions, alternative recession and negative controls without conflating them with observational cosmology.','steps'=>[['cosmic-evolution','Begin with the conventional expansion reference.'],['bubble-universes','Distinguish an observable horizon from a hypothetical physical wall.'],['gravity','Separate common acceleration from tidal deformation and causal interactions.'],['distances','Test which observations could discriminate a physical model.'],['evidence','Require conservation, independent measurements and null controls.']],'quiz'=>[['Does an expanding wall necessarily carry all internal galaxies outward?','No. Interior matter motion requires an independently specified coupling.'],['Does a symmetric Newtonian exterior shell exert an outward interior force?','No. The ideal spherical-shell interior force is zero. A different mechanism must be specified and tested.']]],
 'engineering'=>['id'=>'engineering','title'=>'Build an evidence ledger for propulsion','level'=>'Intermediate','description'=>'Move from hypothetical material intake to a conditional thrust, power and thermal engineering budget.','steps'=>[['physical-first','Identify physical objects and interactions.'],['gravity','Distinguish forces, momentum transfer and common acceleration.'],['dark-matter-drive','Calculate intake, drag, exhaust and energy constraints.'],['evidence','Ask what independent laboratory measurements would be necessary.']],'quiz'=>[['Is collected mass alone evidence of useful propulsion?','No. Exhaust momentum, intake drag, supplied power and heat must all be accounted for.'],['What is the reaction thrust when capture is zero?','Zero in the modeled reaction-mass branch; additional drag can still make net thrust negative.']]]];}
function atlas_edges():array{$edges=[];foreach(topics() as $id=>$t)foreach($t['related'] as $other){$pair=[$id,$other];sort($pair);$edges[implode('|',$pair)]=$pair;}return array_values($edges);}
function glossary():array{return [
 ['term'=>'Absolute progression','definition'=>'The proposed common parameter T used to order physical changes. It is a model assumption, not an independently measured universal clock.','topic'=>'clocks'],
 ['term'=>'Arcsecond','definition'=>'One 3,600th of a degree; a unit of angle used in astronomical measurement.','topic'=>'distances'],
 ['term'=>'Arrival stretch','definition'=>'The ratio of intervals between arrivals and emissions under a declared timing convention. It need not equal energy redshift in every proposed model.','topic'=>'light-history'],
 ['term'=>'Big Bang','definition'=>'The well-supported hot, dense early phase of the observable cosmic history. It does not by itself establish the age of a hypothetical greater cosmos.','topic'=>'cosmic-evolution'],
 ['term'=>'Boundary','definition'=>'A physical interface separating states or domains, if such an interface exists. A cosmological horizon is not automatically a material boundary.','topic'=>'bubble-universes'],
 ['term'=>'Characteristic speed','definition'=>'The propagation parameter in a specified field or dispersion law, distinct from an individual packet’s group speed.','topic'=>'light-history'],
 ['term'=>'Conservation ledger','definition'=>'Separate accounting for energy, momentum and other modeled quantities, including transfer to sources, fields or reservoirs.','topic'=>'evidence'],
 ['term'=>'Distance duality','definition'=>'The standard relation D_L = (1+z)² D_A under the relevant metric and photon-conservation assumptions; a conditional alternative must test its own prediction.','topic'=>'distances'],
 ['term'=>'Extinction','definition'=>'Attenuation of observed light by intervening material, which can bias luminosity-based inference if not modeled.','topic'=>'distances'],
 ['term'=>'Group speed','definition'=>'The propagation speed of a wave packet inferred from the derivative of its dispersion relation. It is not automatically a signal-front speed.','topic'=>'photon-mass'],
 ['term'=>'Hypothesis','definition'=>'A proposed explanation that requires testable predictions and independent evidence; not a finding merely because it is represented in software.','topic'=>'evidence'],
 ['term'=>'Negative control','definition'=>'A deliberately selected condition where an effect should be absent or reversed, testing whether the model or apparatus can fail.','topic'=>'evidence'],
 ['term'=>'Parallax','definition'=>'An apparent angular displacement measured using a known change in observer position. In the calibrated small-angle convention, distance in parsecs is effective baseline in AU divided by parallax in arcseconds.','topic'=>'distances'],
 ['term'=>'Photon rest-energy gap','definition'=>'A stipulated positive rest-energy term in a candidate dispersion law. The zero-gap reference must remain available; a nonzero photon mass is not established here.','topic'=>'photon-mass'],
 ['term'=>'Redshift','definition'=>'A shift of received spectral features toward longer wavelengths relative to a calibrated emission standard; its interpretation depends on the physical model and measurement.','topic'=>'light-history'],
 ['term'=>'Recession','definition'=>'Increasing separation between objects. A kinematic relation alone does not specify its cause or derive the received spectrum.','topic'=>'cosmic-evolution'],
 ['term'=>'Screened field','definition'=>'A candidate field whose influence decreases with a specified range parameter. It must not be confused with ordinary unscreened Newtonian gravity.','topic'=>'gravity'],
 ['term'=>'Surface tension','definition'=>'Energy per area of an idealized interface, generating a resisting term in a spherical pressure–tension force model.','topic'=>'bubble-universes'],
 ['term'=>'Tidal tensor','definition'=>'The spatial gradient of an acceleration field, which predicts differential rather than common acceleration.','topic'=>'gravity'],
 ['term'=>'Waste heat','definition'=>'Energy that must be rejected rather than converted to useful exhaust or other work in an engineering model.','topic'=>'dark-matter-drive']];}
function learning_routes():array{return array_merge(['/learn/','/atlas/','/glossary/','/compare/'],array_map(fn($id)=>'/learn/'.$id.'/',array_keys(learning_paths())));}
function comparison_presets():array{return ['photon-aging'=>['gap'=>0],'clocks'=>['rateB'=>1,'beta'=>0],'big-bang'=>['h0'=>67.4],'recession'=>['gradient'=>0],'bubble'=>['radius'=>1],'shell'=>['alpha'=>0],'population'=>['initial'=>0],'distance'=>['fraction'=>1,'extinction'=>0],'outflow'=>['gap'=>0],'drive'=>['capture'=>0],'escape'=>['ratio'=>0],'parallax'=>['baseline'=>2],'tides'=>['strength'=>0]];}
function compare_request(array $d):array{
 if(!isset($d['experiment'])||!is_string($d['experiment'])||!isset(labs()[$d['experiment']]))throw new InvalidArgumentException('Choose a known experiment.');
 foreach(['left','right'] as $side)if(!isset($d[$side])||!is_array($d[$side])||($d[$side]!==[]&&array_is_list($d[$side])))throw new InvalidArgumentException('Provide left and right parameter objects.');
 $a=calc($d['experiment'],$d['left']);$b=calc($d['experiment'],$d['right']);$diff=[];foreach($a['metrics'] as $i=>$m){$n=$b['metrics'][$i];$delta=is_numeric($m['value'])&&is_numeric($n['value'])?(float)$n['value']-(float)$m['value']:null;if($delta!==null&&!is_finite($delta))throw new RuntimeException('Nonfinite metric difference.');$diff[]=['label'=>$m['label'],'unit'=>$m['unit'],'left'=>$m['value'],'right'=>$n['value'],'delta'=>$delta];}
 return ['schema'=>'beyondspacetime.comparison.v1','version'=>'1.2.0','experiment'=>$d['experiment'],'left'=>$a,'right'=>$b,'differences'=>$diff];
}
function learning_page(string $path,string $method):void{
 if($path==='/learn/'){page_start('Guided learning expeditions','Four structured learning paths through Beyond Spacetime, from foundational concepts to photon measurement, cosmic expansion and propulsion.',$path,'CollectionPage');?><section class="intro"><span class="eyebrow">CHOOSE YOUR EXPEDITION</span><h1>Learn the universe, step by step.</h1><p class="lead">Start with the question that interests you. Each expedition connects explanations, numerical controls and the original ArcSecs sources.</p></section><div class="grid two"><?php foreach(learning_paths() as $i=>$p):?><article class="tile expedition"><span class="pill"><?=h($p['level'])?> · <?=count($p['steps'])?> stages</span><h2><a href="/learn/<?=h($i)?>/"><?=h($p['title'])?></a></h2><p><?=h($p['description'])?></p><a class="text-link" href="/learn/<?=h($i)?>/">Begin expedition →</a></article><?php endforeach;?></div><section class="callout"><h2>Read, calculate, question.</h2><p>Each route is self-paced. Mark stages completed on your device and check your understanding with the supplied answers. No accounts or server-side progress tracking.</p><a href="/atlas/">Explore the relationship atlas →</a></section><?php page_end();return;}
 if(preg_match('~^/learn/([^/]+)/$~',$path,$m)){$p=learning_paths()[$m[1]];page_start($p['title'],$p['description'],$path,'WebPage',false,[['@type'=>'LearningResource','name'=>$p['title'],'description'=>$p['description'],'educationalLevel'=>$p['level'],'learningResourceType'=>'Guided reading and experiments','url'=>BASE.$path,'isAccessibleForFree'=>true]]);?><section class="intro"><a class="text-link" href="/learn/">← All expeditions</a><p class="eyebrow route-level"><?=h($p['level'])?> · Guided expedition</p><h1><?=h($p['title'])?></h1><p class="lead"><?=h($p['description'])?></p></section><section class="panel journey" data-path="<?=h($p['id'])?>"><div class="section-heading"><h2>Mission itinerary</h2><span class="pill" id="journey-count">0 / <?=count($p['steps'])?> complete</span></div><progress id="journey-progress" max="<?=count($p['steps'])?>" value="0"></progress><div class="journey-list"><?php foreach($p['steps'] as $i=>$s):$t=topics()[$s[0]];?><article class="journey-step"><div class="step-number"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></div><div><h3><a href="/concepts/<?=h($t['slug'])?>/"><?=h($t['title'])?></a></h3><p><?=h($s[1])?></p><div class="related-chips"><?php foreach($t['labs'] as $l):?><a href="/labs/<?=h($l)?>/"><?=h(labs()[$l]['title'])?> →</a><?php endforeach;?></div></div><label class="step-check"><input type="checkbox" data-stage="<?=$i?>"> Done</label></article><?php endforeach;?></div><div class="actions"><button class="button secondary js-only" hidden type="button" id="reset-journey">Reset progress</button><span class="muted" id="journey-status">Progress is stored only in this browser when available.</span></div></section><section class="section prose"><h2>Check your understanding</h2><?php foreach($p['quiz'] as $q):?><details class="panel quiz"><summary><?=h($q[0])?></summary><p><?=h($q[1])?></p></details><?php endforeach;?><a class="button" href="/compare/">Test two parameter sets →</a></section><?php page_end();return;}
 if($path==='/atlas/'){page_start('Scientific concept atlas','Explore the relationships between photon physics, time, matter, cosmic expansion, distances, gravity and scientific evidence.',$path,'CollectionPage');$positions=['physical-first'=>[360,208],'foundations'=>[360,65],'photon-mass'=>[140,135],'light-history'=>[85,260],'clocks'=>[180,375],'cosmic-evolution'=>[565,135],'bubble-universes'=>[635,260],'distances'=>[470,390],'gravity'=>[550,310],'dark-matter-drive'=>[360,470],'evidence'=>[360,315]];$labels=['physical-first'=>'Physical first','foundations'=>'Foundations','photon-mass'=>'Photon mass','light-history'=>'Light history','clocks'=>'Clocks','cosmic-evolution'=>'Cosmic evolution','bubble-universes'=>'Bubble domains','distances'=>'Distances','gravity'=>'Gravity','dark-matter-drive'=>'Propulsion','evidence'=>'Evidence'];?><section class="intro"><span class="eyebrow">THE KNOWLEDGE ATLAS</span><h1>Everything is connected.</h1><p class="lead">Follow the editorial links between concepts, not presumed physical causation. Select a node or follow the text index to explore the original explanation and its numerical controls.</p></section><div class="atlas-layout"><section class="panel atlas-panel"><div class="section-heading"><h2>Concept relationships</h2><span class="pill"><?=count(atlas_edges())?> connections</span></div><svg id="atlas-graph" viewBox="0 0 720 530" role="group" aria-label="Linked map of eleven concept guides" xmlns="http://www.w3.org/2000/svg"><g class="atlas-orbits"><circle cx="360" cy="255" r="100"/><circle cx="360" cy="255" r="194"/></g><?php foreach(atlas_edges() as [$a,$b]):?><line class="atlas-edge" data-a="<?=h($a)?>" data-b="<?=h($b)?>" x1="<?=$positions[$a][0]?>" y1="<?=$positions[$a][1]?>" x2="<?=$positions[$b][0]?>" y2="<?=$positions[$b][1]?>"/><?php endforeach;foreach($positions as $id=>[$x,$y]):?><a href="/concepts/<?=h($id)?>/" class="atlas-node" data-node="<?=h($id)?>" aria-label="<?=h(topics()[$id]['title'])?>"><rect x="<?=$x-61?>" y="<?=$y-19?>" width="122" height="38" rx="19"/><text x="<?=$x?>" y="<?=$y+4?>" text-anchor="middle"><?=h($labels[$id])?></text></a><?php endforeach;?></svg><p class="muted">Interactive map: focus or hover a node to highlight its connections; activate it to read the guide.</p></section><aside class="panel"><h2>Navigate the network</h2><label for="atlas-filter">Find a concept</label><input id="atlas-filter" type="search" placeholder="Light, clocks, gravity…" maxlength="100"><p id="atlas-status" role="status">Showing all <?=count(topics())?> guides.</p><div class="atlas-index"><?php foreach(topics() as $t):?><a data-index="<?=h($t['slug'])?>" data-keywords="<?=h($t['title'].' '.$t['category'])?>" href="/concepts/<?=h($t['slug'])?>/"><?=h($t['title'])?> <small><?=h($t['category'])?> · <?=count($t['labs'])?> labs</small></a><?php endforeach;?></div></aside></div><section class="section"><h2>Follow the connections</h2><div class="grid three"><?php foreach(topics() as $t):?><article class="tile"><h3><a href="/concepts/<?=h($t['slug'])?>/"><?=h($t['title'])?></a></h3><div class="related-chips"><?php foreach($t['related'] as $id):?><a href="/concepts/<?=h($id)?>/"><?=h($labels[$id])?> →</a><?php endforeach;?></div></article><?php endforeach;?></div></section><?php page_end();return;}
 if($path==='/glossary/'){page_start('Scientific glossary','Clear definitions of the physical and mathematical terms used in Beyond Spacetime, linked to concepts and original research.',$path,'CollectionPage',false,[['@type'=>'DefinedTermSet','name'=>'Beyond Spacetime glossary','url'=>BASE.$path,'hasDefinedTerm'=>array_map(fn($g)=>['@type'=>'DefinedTerm','name'=>$g['term'],'description'=>$g['definition'],'url'=>BASE.'/concepts/'.$g['topic'].'/'],glossary())]]);?><section class="intro"><span class="eyebrow">THE LANGUAGE OF SCIENCE</span><h1>Find the meaning behind the mathematics.</h1><p class="lead">Plain-language definitions for reading the research, with a distinction between standard scientific terms and proposed model assumptions.</p><label for="glossary-filter">Search definitions</label><input id="glossary-filter" type="search" maxlength="100" placeholder="Try parallax or redshift"><p id="glossary-status" role="status"><?=count(glossary())?> terms</p></section><div class="grid two glossary"><?php foreach(glossary() as $g):?><article class="tile" data-term="<?=h($g['term'].' '.$g['definition'])?>"><h2><?=h($g['term'])?></h2><p><?=h($g['definition'])?></p><a class="text-link" href="/concepts/<?=h($g['topic'])?>/">Explore related concept →</a></article><?php endforeach;?></div><?php page_end();return;}
 if($path==='/compare/'){$id=($method==='POST'?($_POST['experiment']??''):($_GET['experiment']??'photon-aging'));if(!is_string($id)||!isset(labs()[$id]))$id='photon-aging';$l=labs()[$id];$error='';$defaults=['experiment'=>$id,'left'=>[],'right'=>comparison_presets()[$id]];try{$r=compare_request($method==='POST'?['experiment'=>$id,'left'=>$_POST['left']??null,'right'=>$_POST['right']??null]:$defaults);}catch(InvalidArgumentException $e){http_response_code(422);$error=$e->getMessage();$r=compare_request($defaults);}page_start('Compare scientific experiments','Run two parameter sets through the same mathematical model, inspect the numerical differences and preserve the negative control.',$path,'WebPage',$method==='POST'||isset($_GET['experiment']));?><section class="intro"><span class="eyebrow">CONTROL VS. CANDIDATE</span><h1>Compare two worlds.</h1><p class="lead">Change physical parameters without changing the underlying equation. The same server-side solver evaluates both cases, and the difference column is right minus left.</p><form class="compare-select" method="get" action="/compare/"><label for="experiment-select">Choose a model</label><div class="actions"><select id="experiment-select" name="experiment"><?php foreach(labs() as $key=>$lab):?><option value="<?=h($key)?>" <?=$id===$key?'selected':''?>><?=h($lab['title'])?></option><?php endforeach;?></select><button class="button secondary">Load model</button></div></form></section><section class="panel"><h2><?=h($l['title'])?></h2><p class="formula"><?=h($l['equation'])?></p><?php if($error):?><p class="notice error" role="alert"><?=h($error)?> Default cases displayed.</p><?php endif;?><form method="post" action="/compare/" id="compare-form"><input type="hidden" name="experiment" value="<?=h($id)?>"><div class="grid two"><?php foreach(['left'=>'Case A · reference','right'=>'Case B · comparison'] as $side=>$label):?><fieldset class="case-fields"><legend><?=h($label)?></legend><?php foreach($l['params'] as $p):?><div class="field"><label for="<?=h($side.'-'.$p['key'])?>"><?=h($p['label'].' '.$p['unit'])?></label><input required type="number" id="<?=h($side.'-'.$p['key'])?>" name="<?=h($side.'['.$p['key'].']')?>" min="<?=h($p['min'])?>" max="<?=h($p['max'])?>" step="any" value="<?=h($r[$side]['parameters'][$p['key']])?>"></div><?php endforeach;?></fieldset><?php endforeach;?></div><div class="actions"><button class="button" type="submit">Run both cases</button><button type="button" class="button secondary js-only" hidden id="copy-case">Copy A to B</button><a class="button secondary" href="/compare/?experiment=<?=h($id)?>">Reset comparison</a></div></form></section><section class="section" id="comparison-output"><h2>Calculated differences</h2><div class="panel table-scroll"><table><caption>Same model · right minus left (categorical results have no numerical difference)</caption><thead><tr><th scope="col">Quantity</th><th scope="col">A</th><th scope="col">B</th><th scope="col">B − A</th></tr></thead><tbody><?php foreach($r['differences'] as $d):?><tr><th scope="row"><?=h($d['label'])?> <small><?=h($d['unit'])?></small></th><td><?=h(num($d['left']))?></td><td><?=h(num($d['right']))?></td><td><?=h($d['delta']===null?'—':num($d['delta']))?></td></tr><?php endforeach;?></tbody></table></div><div class="grid two section comparison-charts"><?php foreach(['left'=>'Case A','right'=>'Case B'] as $side=>$label):?><figure class="panel"><h3><?=h($label)?></h3><?=chart_svg($r[$side],$r[$side==='left'?'right':'left'])?><figcaption class="legend"><?php foreach($r[$side]['series'] as $i=>$name):?><span><i class="swatch series-<?=$i?>"></i><?=h($name)?></span><?php endforeach;?></figcaption><?php if($r[$side]['note']):?><p class="notice"><?=h($r[$side]['note'])?></p><?php endif;?></figure><?php endforeach;?></div><p class="muted">Both plots use the same numerical axis ranges. The trajectories are conditional calculations, not observations.</p><button type="button" id="export-comparison" class="button secondary js-only" hidden>Export both complete results</button><script id="comparison-data" type="application/json"><?=j($r)?></script></section><section class="callout"><h2>Interpret with care.</h2><p><?=h($l['limitation'])?></p><p><a href="/labs/<?=h($id)?>/">Single experiment →</a> · <a href="<?=h($l['sourceUrl'])?>">Original research ↗</a></p></section><?php page_end();return;}
